/**
 * Daily Digest articles. Body convention (rendered by components/daily-digest/ArticleBody):
 * - Section title: a paragraph starting with "## " → <h2>; "### " → <h3>.
 * - Bulleted list: consecutive paragraphs starting with "- " (or "* ").
 * - Numbered list: consecutive paragraphs starting with "1. " (or "1) ").
 * - Anything else is a normal paragraph. One string may also hold several lines split by "\n".
 * Example:
 *   paragraphs: ["## Why it matters", "Short intro.", "- first point", "- second point", "1. Do this", "2. Then this"]
 * Optional: `sections: [{ heading: "Why it matters", body: ["Short intro.", "- first point"] }]`
 * renders after `paragraphs`, each heading as <h2>.
 */
export type PostTag = "Technique" | "Deep dive" | "Essay";
/** Byline + JSON-LD kind (board GO, Oct 3 2026). Omitted = "technique". Essays carry the author's byline. */
export type PostKind = "essay" | "technique";

/**
 * Hero art (SPEC v2 §3/§4, sticker batch v3.1, Oct 2 2026). One 16:9 file (1920×1080) under public/art/digest/,
 * `<slug>-sticker.webp`, used for the card AND the story hero (same URL, so the card→story morph pairs and the hero
 * is already cached). It is never cropped: slots show it with object-fit: contain on `pad`, the art's own background
 * colour (Digest 5-colour cycle, art-src/palette.json). `alt` is final copy (ART-ALT-DRAFT.md, "Digest: FINAL alt text"),
 * one plain sentence, used exactly.
 */
export type PostHero = { src: string; alt: string; pad: string };

/**
 * Pull quote (SPEC §8, v1.2): `text` must be a verbatim line from this article's body (the test suite checks it).
 * It renders right after the paragraph that contains it. `cite` is shown in meta type under the quote.
 */
export type PostPullQuote = { text: string; cite?: string };

export type PostUpdated = { date: string; note: string };

export type Post = {
  slug: string;
  title: string;
  dek: string;
  date: string;
  /** Index + article meta tag. Omitted = "Technique". */
  tag?: PostTag;
  /** Byline kind. Omitted = "technique" ("Daily Digest · Edited by …"); "essay" = "By …" + bio. */
  kind?: PostKind;
  /** Per-article sticker art (card + story hero + alt + pad). Required: there is no fallback art. */
  hero: PostHero;
  /** One-line dek (≤70, COPY.md v2) for cards AND the story page under the H1, so they match. Omitted = `dek`. */
  cardDek?: string;
  pullQuote?: PostPullQuote;
  /**
   * Latest real update only (Release B). date: YYYY-MM-DD, strictly after `date`; note: ≤ 90 chars, ends with a period.
   * Shows "Updated <Mon D>: <note>" under the byline, the Updated card mark for readers who opened it before that day,
   * and refreshes the RSS item and sitemap lastmod. Never add one for a non-real change.
   */
  updated?: PostUpdated;
  sourceNote?: string;
  paragraphs: string[];
  sections?: { heading: string; body: string[] }[];
};

